import{_ as o,o as t,c,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"G2 — Creator Upload (Giai đoạn 1 / MVP)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g2-creator-upload/spec.md","filePath":"mobile/features/g2-creator-upload/spec.md"}'),d={name:"mobile/features/g2-creator-upload/spec.md"};function a(n,e,r,l,h,s){return t(),c("div",null,[...e[0]||(e[0]=[i('<h1 id="g2-—-creator-upload-giai-đoan-1-mvp" tabindex="-1">G2 — Creator Upload (Giai đoạn 1 / MVP) <a class="header-anchor" href="#g2-—-creator-upload-giai-đoan-1-mvp" aria-label="Permalink to &quot;G2 — Creator Upload (Giai đoạn 1 / MVP)&quot;">​</a></h1><p>&gt; Tham chiếu: <code>docs/mobile/mobile-app-plan.md</code> mục 2 (thiết kế đã chốt, KHÔNG mâu thuẫn với file này). &gt; Trạng thái: DRAFT — spec thuần, không có code.</p><h2 id="_1-muc-tieu-pham-vi" tabindex="-1">1. Mục tiêu &amp; phạm vi <a class="header-anchor" href="#_1-muc-tieu-pham-vi" aria-label="Permalink to &quot;1. Mục tiêu &amp; phạm vi&quot;">​</a></h2><p>Creator quay/chọn video tại hiện trường, upload trực tiếp lên S3 (presigned PUT), gắn vào 1 Task đã được giao, lưu thành 1 bản ghi Material Repository với <code>type = RAW</code>.</p><p>Chỉ làm <strong>Phase 1 MVP</strong> theo <code>mobile-app-plan.md</code> mục 2:</p><ul><li>Task list (được giao sẵn) → Task detail → quay video / chọn từ gallery → upload (progress bar, retry) → gắn vào Task → lưu Material RAW.</li></ul><p><strong>KHÔNG</strong> làm trong G2 (xem mục 7): AI edit raw footage, auto-caption, tự tạo Task mới. Đó là G8 / Phase 2 — placeholder, chưa thiết kế.</p><h2 id="_2-điem-cham-he-thong-hien-co" tabindex="-1">2. Điểm chạm hệ thống hiện có <a class="header-anchor" href="#_2-điem-cham-he-thong-hien-co" aria-label="Permalink to &quot;2. Điểm chạm hệ thống hiện có&quot;">​</a></h2><p>Đã đọc trực tiếp các file sau (không đoán):</p><table tabindex="0"><thead><tr><th>File</th><th>Hiện trạng</th><th>Dùng được ngay?</th></tr></thead><tbody><tr><td><code>controller/UploadS3Controller.java</code></td><td><code>POST /api/v1/test/upload</code> — test-only, dùng <code>UUID.randomUUID()</code> làm fake user, gọi <code>fileStorageService.uploadAvatar(...)</code>.</td><td>KHÔNG — phải thay bằng 2 endpoint chính thức mới (mục 3), không tái dùng controller này.</td></tr><tr><td><code>service/FileStorageService.java</code></td><td>Có <code>uploadMaterial(workspaceId, bytes, contentType, filename)</code> (multipart, qua server), <code>createPresignedDownloadUrl(s3Key)</code> (presigned <strong>GET</strong>, đã có), <code>uploadObject</code>/<code>downloadObject</code>/<code>deleteObject</code>/<code>objectUrl</code> (theo key tuỳ ý).</td><td><strong>Presigned PUT (upload) CHƯA có</strong> — chỉ có presigned GET (download). Phải thêm method mới vào interface + impl.</td></tr><tr><td><code>service/impl/S3FileStorageServiceImpl.java</code></td><td>Có <code>S3Presigner</code> đã autowired, dùng cho <code>presignGetObject</code>. Pattern key: <code>image/&lt;folder&gt;/&lt;ownerId&gt;/&lt;epochMillis&gt;.&lt;ext&gt;</code> cho ảnh qua <code>uploadMaterial</code>; <code>resolveBucket(key)</code> tách prefix <code>qwen-ambassador/</code> sang bucket AI riêng.</td><td>Cần thêm <code>createPresignedUploadUrl(key, contentType, ttlSeconds)</code> dùng <code>s3Presigner.presignPutObject(...)</code> — pattern tương tự <code>createPresignedDownloadUrl</code> đã có, chỉ đổi <code>PutObjectPresignRequest</code>.</td></tr><tr><td><code>document/MaterialDocument.java</code></td><td>Field thật: <code>id</code>, <code>workspaceId</code> (<code>workspace_id</code>), <code>name</code>, <code>originalName</code> (<code>original_name</code>), <code>type</code> (enum <code>MaterialType</code>), <code>mimeType</code> (<code>mime_type</code>), <code>fileSize</code> (<code>file_size</code>), <code>url</code>, <code>s3Key</code> (<code>s3_key</code>), <code>parentMaterialId</code>, <code>watermarkMeta</code>, <code>createdBy</code> (<code>created_by</code>), <code>createdAt</code>, <code>updatedAt</code>. <strong>Không có field liên kết Task</strong> (<code>taskId</code>) — đây là field MỚI cần thêm nếu muốn lưu liên kết Material ↔ Task trực tiếp trên document.</td><td>Thêm field <code>taskId</code> (và tuỳ chọn <code>source = &quot;MOBILE_CREATOR_UPLOAD&quot;</code>) vào <code>MaterialDocument</code> — NEW.</td></tr><tr><td><code>controller/MaterialController.java</code> + <code>service/impl/MaterialServiceImpl.java</code></td><td><code>POST /api/v1/workspaces/{workspaceId}/materials</code> nhận <code>MultipartFile</code>, role <code>MANAGER</code>/<code>CREATOR</code>, gọi <code>materialService.uploadMaterial(workspaceId, user, file)</code> → upload qua <code>fileStorageService.uploadMaterial</code> (server trung gian, convert ảnh sang WebP) → lưu <code>MaterialDocument</code> với <code>type = MaterialType.RAW</code>. Đây là <strong>upload qua server</strong>, không phải presigned-PUT-từ-client. Video không nên đi qua nhánh <code>uploadImage</code> (convert WebP) — nhánh đó chỉ hợp lý cho ảnh.</td><td>Cần endpoint <strong>confirm</strong> riêng cho mobile (không multipart, không qua server) — xem mục 3.2.</td></tr><tr><td><code>model/Task.java</code> (JPA, Postgres)</td><td>Entity tối giản: <code>id</code>, <code>workspaceId</code>, <code>type</code> (<code>TaskType</code>), <code>title</code>, <code>createdBy</code>, timestamps. <strong>Không có <code>assigneeId</code></strong> — ghi chú ngay trong code: &quot;Minimal Task entity... no assignee&quot;.</td><td>Task JPA KHÔNG đủ cho &quot;Task được giao cho Creator&quot;. Phải dùng <code>TaskDocument</code> (Mongo) — có <code>assigneeId</code>.</td></tr><tr><td><code>document/TaskDocument.java</code> (Mongo)</td><td>Field thật: <code>id</code>, <code>workspaceId</code>, <code>campaignId</code>, <code>type</code> (<code>TaskType</code>), <code>name</code>, <code>status</code> (string, mặc định <code>&quot;TODO&quot;</code>), <code>assigneeId</code>, <code>dueDate</code>, <code>publishDate</code>, <code>cancellation</code>, v.v. Đây là nguồn sự thật cho workflow Task V2.</td><td>Dùng <code>TaskDocument.id</code> + <code>assigneeId</code> + <code>status</code> để xác định &quot;Task giao cho Creator này, chưa FINISHED/CANCELLED&quot;.</td></tr><tr><td><code>model/enums/TaskType.java</code></td><td><code>POST, LIVESTREAM, SURVEY, EVENT_PLAN, PRESS_RECOMMENDATION</code></td><td>Không có type riêng cho &quot;creator upload&quot; — không cần, Material gắn vào Task bất kỳ type nào.</td></tr><tr><td><code>docs/ba/05-content-task-workflow.md</code> §7 (FR 3.6.11–3.6.17)</td><td>3.6.11–3.6.14: CRUD Material Repository chuẩn. 3.6.15: Apply Watermark (role CREATOR). 3.6.16: Download Material (CREATOR/CLIENT/MANAGER). Không có rule riêng nào về raw/retouched khác với field <code>type</code> enum đã thấy trong <code>MaterialDocument</code>/<code>MaterialType</code>.</td><td>Material RAW tạo từ mobile dùng đúng <code>MaterialType.RAW</code> đã có, không cần enum mới.</td></tr><tr><td><code>brandhub-mobile-app/package.json</code></td><td>Có <code>expo-file-system</code> (<code>~56.0.7</code>). <strong>Không thấy</strong> <code>expo-camera</code> hoặc <code>expo-image-picker</code>.</td><td>Cả hai package này là NEW — cần <code>expo install expo-camera expo-image-picker</code>.</td></tr></tbody></table><h2 id="_3-api-moi-can-them-o-business-service" tabindex="-1">3. API mới cần thêm ở business-service <a class="header-anchor" href="#_3-api-moi-can-them-o-business-service" aria-label="Permalink to &quot;3. API mới cần thêm ở business-service&quot;">​</a></h2><p>Namespace đề xuất: tái dùng <code>MaterialController</code> (<code>/api/v1/workspaces/{workspaceId}/materials</code>), thêm 2 endpoint con dưới <code>/upload-session</code> để không đụng endpoint multipart hiện có.</p><h3 id="_3-1-post-api-v1-workspaces-workspaceid-materials-upload-session" tabindex="-1">3.1. <code>POST /api/v1/workspaces/{workspaceId}/materials/upload-session</code> <a class="header-anchor" href="#_3-1-post-api-v1-workspaces-workspaceid-materials-upload-session" aria-label="Permalink to &quot;3.1. `POST /api/v1/workspaces/{workspaceId}/materials/upload-session`&quot;">​</a></h3><p>Xin presigned PUT URL.</p><ul><li>Role: <code>CREATOR</code> (dùng <code>@RequireRole({MemberRole.CREATOR})</code> — KHÔNG mở cho MANAGER/CLIENT, vì đây là thao tác quay/upload hiện trường của Creator).</li><li>Request body: <ul><li><code>taskId</code> (String, bắt buộc) — id của <code>TaskDocument</code>.</li><li><code>filename</code> (String, bắt buộc)</li><li><code>contentType</code> (String, bắt buộc — whitelist <code>video/mp4</code>, <code>video/quicktime</code>; từ chối type khác)</li><li><code>fileSize</code> (Long, bắt buộc — dùng để validate giới hạn, xem mục 8)</li></ul></li><li>Logic server phải làm trước khi cấp URL: <ol><li>Load <code>TaskDocument</code> theo <code>taskId</code>. Không tồn tại → 404.</li><li>Check <code>task.workspaceId == workspaceId</code> (path) — lệch → 403.</li><li>Check <code>task.assigneeId == user.id</code> (user hiện tại từ <code>AuthenticatedUser</code>) — khác → 403 <code>TASK_NOT_ASSIGNED</code>.</li><li>Check <code>task.status</code> không phải <code>FINISHED</code>/<code>CANCELLED</code> — nếu là thì 409 <code>TASK_NOT_ACTIVE</code>.</li><li>Sinh S3 key mới, pattern đề xuất theo convention đã có trong <code>S3FileStorageServiceImpl</code>: <code>video/materials/{workspaceId}/{taskId}/{epochMillis}-{uuid}.{ext}</code>.</li><li>Gọi method MỚI <code>fileStorageService.createPresignedUploadUrl(key, contentType, ttlSeconds)</code> (xem mục 2, cần thêm vào <code>FileStorageService</code> + impl, dùng <code>s3Presigner.presignPutObject(...)</code>, pattern giống <code>createPresignedDownloadUrl</code> đã có).</li></ol></li><li>Response: <ul><li><code>uploadUrl</code> (presigned PUT URL)</li><li><code>s3Key</code></li><li><code>expiresAt</code> (Instant, TTL đề xuất 15 phút — đủ cho file vài trăm MB trên mạng di động trung bình, xem mục 5/6 về hết hạn giữa chừng)</li></ul></li></ul><h3 id="_3-2-post-api-v1-workspaces-workspaceid-materials-upload-session-confirm" tabindex="-1">3.2. <code>POST /api/v1/workspaces/{workspaceId}/materials/upload-session/confirm</code> <a class="header-anchor" href="#_3-2-post-api-v1-workspaces-workspaceid-materials-upload-session-confirm" aria-label="Permalink to &quot;3.2. `POST /api/v1/workspaces/{workspaceId}/materials/upload-session/confirm`&quot;">​</a></h3><p>Xác nhận đã PUT xong lên S3, tạo Material record.</p><ul><li>Role: <code>CREATOR</code> (giống 3.1).</li><li>Request body: <ul><li><code>s3Key</code> (String, bắt buộc — key đã nhận ở 3.1)</li><li><code>taskId</code> (String, bắt buộc)</li><li><code>filename</code> / <code>originalName</code> (String)</li><li><code>contentType</code> (String)</li><li><code>fileSize</code> (Long)</li></ul></li><li>Logic server: <ol><li>Re-check quyền (assignee + task status) như 3.1 — không tin tưởng lại response của bước trước, vì có thể có khoảng trễ (task bị huỷ giữa lúc upload).</li><li>Idempotency: check đã tồn tại <code>MaterialDocument</code> với <code>s3Key</code> này chưa (tránh confirm trùng do retry) — nếu có, trả lại record cũ, không tạo mới (xem mục 6, duplicate case).</li><li>(Tuỳ chọn, KHÔNG bắt buộc ở MVP) HEAD object trên S3 để verify file thực sự tồn tại tại key đó trước khi lưu DB — tránh record &quot;ma&quot; nếu client confirm sai hoặc PUT thất bại âm thầm. Đánh dấu là rủi ro mở ở mục 8 nếu bỏ qua.</li><li>Build <code>objectUrl(s3Key)</code> (method đã có trong <code>FileStorageService</code>) làm <code>url</code>.</li><li>Lưu <code>MaterialDocument</code>: <code>workspaceId</code>, <code>name = filename</code>, <code>originalName</code>, <code>type = MaterialType.RAW</code>, <code>mimeType = contentType</code>, <code>fileSize</code>, <code>url</code>, <code>s3Key</code>, <code>createdBy = user.id</code>, <strong><code>taskId</code> (field mới cần thêm vào <code>MaterialDocument</code>)</strong>.</li></ol></li><li>Response: <code>MaterialResponse</code> đã có sẵn trong <code>MaterialServiceImpl.toResponse(...)</code> — cần thêm <code>taskId</code> vào <code>MaterialResponse</code> DTO song song với field mới trên document.</li></ul><h3 id="luu-y-thiet-ke" tabindex="-1">Lưu ý thiết kế <a class="header-anchor" href="#luu-y-thiet-ke" aria-label="Permalink to &quot;Lưu ý thiết kế&quot;">​</a></h3><ul><li>Không tái dùng <code>/api/v1/test/upload</code> — xoá hoặc giữ lại chỉ cho mục đích test nội bộ, không public cho mobile.</li><li><code>uploadAvatar</code>/<code>uploadMaterial</code> (qua server, multipart) KHÔNG dùng cho video — giữ nguyên cho ảnh, vì nhánh đó convert sang WebP (không áp dụng cho video) và đi qua server (không phù hợp file vài trăm MB).</li></ul><h2 id="_4-luong-man-hinh-mobile" tabindex="-1">4. Luồng màn hình mobile <a class="header-anchor" href="#_4-luong-man-hinh-mobile" aria-label="Permalink to &quot;4. Luồng màn hình mobile&quot;">​</a></h2><ol><li><strong>Task List (assigned)</strong> — gọi API Task hiện có, lọc theo <code>assigneeId = currentUser</code> và <code>status</code> chưa <code>FINISHED</code>/<code>CANCELLED</code>. (Việc list Task là scope G5, G2 chỉ cần đủ để chọn Task đích — có thể dùng tạm 1 API Task đơn giản nếu G5 chưa làm; không thiết kế lại toàn bộ Task list ở đây.)</li><li><strong>Task Detail</strong> — thêm 2 nút mới: &quot;Quay video&quot; / &quot;Chọn từ thư viện&quot;. <ul><li>Quay video: <code>expo-camera</code> (NEW dependency) — mở camera trong app, ghi ra file local (<code>expo-file-system</code> cache dir).</li><li>Chọn từ thư viện: <code>expo-image-picker</code> (NEW dependency), <code>mediaTypes: Videos</code>.</li></ul></li><li><strong>Màn Upload</strong> (sau khi có file local URI): <ul><li>Hiển thị tên file, dung lượng, nút &quot;Bắt đầu upload&quot;.</li><li>Gọi 3.1 lấy <code>uploadUrl</code> + <code>s3Key</code>.</li><li>PUT file lên <code>uploadUrl</code> bằng <code>FileSystem.createUploadTask</code> (xem mục 5), progress bar theo callback.</li><li>PUT xong → gọi 3.2 confirm.</li><li>Thành công → màn &quot;Đã gắn vào Task&quot; (hiển thị tên Material, link quay lại Task Detail, Material giờ xuất hiện trong list Material của Task/Workspace).</li></ul></li><li>Giới hạn Expo managed đã chốt trong <code>mobile-app-plan.md</code>: upload chỉ chạy khi app đang mở foreground — nếu user thoát app/khóa máy giữa lúc upload, tiến trình dừng, phải resume khi mở lại app (không có background transfer thật ở giai đoạn này).</li></ol><h2 id="_5-upload-resilience" tabindex="-1">5. Upload resilience <a class="header-anchor" href="#_5-upload-resilience" aria-label="Permalink to &quot;5. Upload resilience&quot;">​</a></h2><ul><li>Dùng <code>FileSystem.createUploadTask(uploadUrl, fileUri, { httpMethod: &#39;PUT&#39;, headers: { &#39;Content-Type&#39;: contentType } }, progressCallback)</code> của <code>expo-file-system</code> — hỗ trợ progress callback, chạy foreground.</li><li>Đây là PUT đơn (không phải S3 Multipart Upload API thật — multipart upload S3 cần nhiều presigned URL theo part, phức tạp hơn nhiều so với effort capstone cho phép). MVP dùng 1 presigned PUT duy nhất cho toàn file.</li><li>Retry khi mất mạng giữa chừng: <strong>restart từ đầu</strong>, không resume byte-level — vì presigned PUT đơn không hỗ trợ resume (khác hẳn S3 Multipart hoặc TUS protocol). Giữ file local nguyên vẹn (không xoá cache) cho tới khi confirm (3.2) thành công, để có thể bấm &quot;Thử lại&quot; mà không phải quay/chọn lại video.</li><li>Retry strategy cụ thể: tối đa 3 lần tự động retry khi lỗi network (không phải lỗi 4xx), backoff đơn giản (ví dụ 2s/5s/10s); quá 3 lần → báo lỗi, cho nút &quot;Thử lại&quot; thủ công.</li><li>Trade-off ghi nhận rõ: nếu video lớn (vài trăm MB) và mạng rớt ở 90%, phải PUT lại từ đầu — đây là hạn chế đã biết của approach &quot;presigned PUT đơn + Expo managed foreground-only&quot;, không phải bug. Nâng cấp thật (resumable) cần S3 Multipart Upload (nhiều presigned URL theo part + ETag ghép) — để dành cho sau nếu pain point này xuất hiện thực tế.</li></ul><h2 id="_6-error-cases" tabindex="-1">6. Error cases <a class="header-anchor" href="#_6-error-cases" aria-label="Permalink to &quot;6. Error cases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>Xử lý</th></tr></thead><tbody><tr><td>Mất mạng giữa upload</td><td>Giữ file local, auto-retry theo mục 5, hết retry thì cho thử lại thủ công; không mất file đã quay/chọn.</td></tr><tr><td>Presigned URL hết hạn giữa khi upload (TTL 15 phút)</td><td>PUT lên S3 trả lỗi 403 (signature expired). Client phát hiện lỗi 403 từ PUT → gọi lại 3.1 lấy URL mới với <strong>cùng s3Key cũ hoặc key mới</strong> (đề xuất: key mới, đơn giản hơn vì không cần lo PUT 1 phần dữ liệu cũ còn sót) → PUT lại từ đầu.</td></tr><tr><td>Duplicate upload (confirm gọi 2 lần, hoặc user bấm 2 lần)</td><td>3.2 idempotent theo <code>s3Key</code> (mục 3.2 bước 2) — trả lại Material đã tạo, không tạo bản ghi trùng.</td></tr><tr><td>Task không giao cho Creator này</td><td>403 <code>TASK_NOT_ASSIGNED</code> ở cả 3.1 và 3.2 (check lại, không tin request trước).</td></tr><tr><td>Task đã <code>FINISHED</code>/<code>CANCELLED</code></td><td>409 <code>TASK_NOT_ACTIVE</code> ở cả 3.1 và 3.2.</td></tr><tr><td>Client mất kết nối sau khi PUT xong nhưng trước khi gọi confirm (3.2)</td><td>File đã nằm trên S3 nhưng chưa có Material record. Khi mở lại app, hiển thị trạng thái &quot;đang chờ xác nhận&quot; (lưu <code>s3Key</code> tạm ở local state) và cho phép gọi lại 3.2 trực tiếp (không cần PUT lại) — cần client giữ <code>s3Key</code> + <code>taskId</code> ở local storage cho tới khi confirm xong.</td></tr></tbody></table><h2 id="_7-viec-khong-lam-o-g2" tabindex="-1">7. Việc KHÔNG làm ở G2 <a class="header-anchor" href="#_7-viec-khong-lam-o-g2" aria-label="Permalink to &quot;7. Việc KHÔNG làm ở G2&quot;">​</a></h2><ul><li>Không AI auto-edit raw footage (cắt short, chọn đoạn đẹp) — đó là G8/Phase 2, phụ thuộc năng lực AI edit thật chưa tồn tại (<code>AiVideoService</code> hiện tại chỉ generate từ prompt, không edit video có sẵn).</li><li>Không auto-caption.</li><li>Không tự động tạo Task mới ở trạng thái <code>IN_REVIEW</code> sau khi upload — Material RAW chỉ gắn vào Task đã có, Creator hoặc Manager xử lý tiếp bằng tay theo workflow hiện tại.</li><li>Không làm S3 Multipart Upload (resumable thật theo part) — chỉ presigned PUT đơn (mục 5).</li><li>Không làm background upload khi app bị kill/minimize (đã chốt ở <code>mobile-app-plan.md</code> mục 1).</li></ul><h2 id="_8-rui-ro-cau-hoi-mo" tabindex="-1">8. Rủi ro / câu hỏi mở <a class="header-anchor" href="#_8-rui-ro-cau-hoi-mo" aria-label="Permalink to &quot;8. Rủi ro / câu hỏi mở&quot;">​</a></h2><ol><li><strong>Giới hạn dung lượng file</strong>: chưa có policy max file size rõ ràng. Cần chốt (đề xuất: 500MB–1GB cho video raw hiện trường) và validate ở bước 3.1 (so <code>fileSize</code> request với giới hạn) trước khi cấp presigned URL — tránh cấp URL cho file quá lớn rồi thất bại giữa chừng.</li><li><strong><code>createPresignedUploadUrl</code> là method mới</strong> phải thêm vào interface <code>FileStorageService</code> + impl <code>S3FileStorageServiceImpl</code> (dùng <code>S3Presigner.presignPutObject</code>, pattern giống <code>createPresignedDownloadUrl</code> đã có sẵn) — xác nhận lại với backend dev trước khi implement, vì đây là thay đổi interface public.</li><li><strong>Video compression trước khi upload</strong>: MVP KHÔNG làm (giữ nguyên file gốc từ camera/gallery) để tránh risk + effort xử lý video client-side trong Expo managed (cần <code>ffmpeg-kit</code> hoặc native module, không có sẵn). Nếu dung lượng video quá lớn gây vấn đề thực tế trong demo, xem xét giảm resolution record trong <code>expo-camera</code> config (ví dụ 720p) thay vì compress sau khi quay.</li><li><strong>Field <code>taskId</code> trên <code>MaterialDocument</code> là thay đổi schema mới</strong> — cần xác nhận không ảnh hưởng dữ liệu Material cũ (field optional/nullable, materials tạo từ web trước đây không có <code>taskId</code>).</li><li><strong>HEAD-object verify trước khi lưu Material (3.2 bước 3)</strong>: MVP có thể bỏ qua để đơn giản, đổi lại chấp nhận rủi ro nhỏ Material record &quot;ma&quot; nếu client confirm sai — cần quyết định có đáng làm thêm bước verify này không trong thời gian capstone còn lại.</li></ol>',30)])])}const u=o(d,[["render",a]]);export{p as __pageData,u as default};
